text:
Here's your water tracker: tap a glass to add it, and it counts toward your goal of 8 glasses. It starts fresh each day and saves on this device if your app allows it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; background: #eef7fb; color: #12384a; margin: 0; padding: 24px; text-align: center; }
  h1 { font-size: 1.4rem; margin: 0 0 4px; }
  #date { color: #5b8497; margin-bottom: 16px; }
  #count { font-size: 2.6rem; font-weight: 700; margin: 8px 0; }
  #bar { height: 14px; background: #d3e8f1; border-radius: 7px; overflow: hidden; max-width: 320px; margin: 0 auto 16px; }
  #fill { height: 100%; width: 0; background: #2a9fd6; transition: width .25s; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 340px; margin: 0 auto 16px; }
  .g { width: 56px; height: 64px; border: 2px solid #2a9fd6; border-radius: 4px 4px 12px 12px; background: #fff; cursor: pointer; font-size: 1.6rem; padding: 0; }
  .g.full { background: #2a9fd6; color: #fff; }
  .row button { font-size: 1rem; padding: 8px 16px; margin: 4px; border: 0; border-radius: 8px; background: #12384a; color: #fff; cursor: pointer; }
  .row button.alt { background: #8aa9b8; }
  #msg { min-height: 1.4em; margin-top: 12px; font-weight: 600; }
</style>
</head>
<body>
  <h1>💧 Daily water</h1>
  <div id="date"></div>
  <div id="count"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div class="row">
    <button type="button" id="add">+ Add a glass</button>
    <button type="button" id="remove" class="alt">− Remove one</button>
    <button type="button" id="reset" class="alt">Reset</button>
  </div>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key), 10) || 0; } catch (e) {}

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("count").textContent = n + " / " + GOAL + " glasses";
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    var total = Math.max(GOAL, n);
    for (var i = 0; i < total; i++) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "g" + (i < n ? " full" : "");
      b.textContent = i < n ? "💧" : "";
      (function (idx) {
        b.onclick = function () { n = (idx + 1 === n) ? idx : idx + 1; save(); draw(); };
      })(i);
      box.appendChild(b);
    }
    var msg = document.getElementById("msg");
    if (n >= GOAL) msg.textContent = "Goal reached. Well hydrated! 🌿";
    else msg.textContent = (GOAL - n) + " more to go.";
  }

  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("remove").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```
